WHERE class_id IN (
    'c0000000-0000-0000-0000-000000000001', -- Pre 9th
    'c0000000-0000-0000-0000-000000000002', -- Class 9
    'c0000000-0000-0000-0000-000000000003'  -- Class 10
);

